<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoices</title><link rel="stylesheet" href="<?=base_url('styles.css')?>"><style>body{background:#090b0d;color:#eee}.wrap{max-width:1200px;margin:auto;padding:30px}.top{display:flex;justify-content:space-between;align-items:center;gap:15px}.top h1{font:500 42px Georgia,serif}.btn{padding:10px 14px;border:1px solid #4b4337;border-radius:9px;color:#e7d2aa;text-decoration:none;background:#171717}.primary{background:#c6a66e;color:#111}.filters{display:flex;gap:8px;margin:18px 0}.filters input,.filters select{padding:10px;background:#111;color:#eee;border:1px solid #333;border-radius:8px}.table{width:100%;border-collapse:collapse;background:#111416}.table th,.table td{padding:13px;border-bottom:1px solid #292929;text-align:left}.pill{font-size:10px}.@media(max-width:700px){.top,.filters{flex-direction:column;align-items:stretch}}</style></head><body><div class="wrap"><div class="top"><div><div style="color:#c8a66e;font-size:11px;letter-spacing:.15em">LEX FACTUM · BILLING</div><h1>Invoices</h1></div><a class="btn primary" href="<?=site_url('admin/invoices/create')?>">+ New Invoice</a></div><form class="filters"><input name="q" value="<?=esc($q)?>" placeholder="Search invoice / client / matter"><select name="status"><option value="">All status</option><?php foreach(['UNPAID','PARTIAL','PAID'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn">Filter</button></form><table class="table"><tr><th>Invoice</th><th>Client</th><th>Matter</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr><?php if(!$invoices):?><tr><td colspan="7">No invoices yet.</td></tr><?php endif;?><?php foreach($invoices as $i):?><tr><td><b><?=esc($i['invoice_no'])?></b></td><td><?=esc($i['client_name'])?></td><td><?=esc($i['case_reference']?:'—')?></td><td><?=date('d M Y',strtotime($i['invoice_date']))?></td><td>₹ <?=number_format($i['total'],2)?></td><td class="pill"><?=esc($i['payment_status'])?></td><td><a class="btn" href="<?=site_url('admin/invoices/'.$i['id'])?>">Open</a></td></tr><?php endforeach;?></table></div></body></html>
